parameters.jsCode:
// Score Lead: merges lead data with AI output, calculates total score and category

const lead = $('Config').item.json;
const ai = $json.output || {};

// keep each score inside its allowed range, even if AI returns something weird
const clamp = (value, max) => Math.max(0, Math.min(max, Number(value) || 0));

const budgetScore = clamp(ai.budget_score, 30);
const authorityScore = clamp(ai.authority_score, 20);
const needScore = clamp(ai.need_score, 30);
const timelineScore = clamp(ai.timeline_score, 20);
const totalScore = budgetScore + authorityScore + needScore + timelineScore;

// "none" from the JSON example means no red flags
// works even if AI returns something that is not a list
const rawFlags = Array.isArray(ai.red_flags) ? ai.red_flags : [];
const redFlags = rawFlags
  .map(f => String(f).trim())
  .filter(f => f && f.toLowerCase() !== 'none');

const hot = Number(lead.hot_threshold);
const warm = Number(lead.warm_threshold);

let category;
if (ai.is_spam === true) {
  category = 'spam';
} else if (totalScore >= hot) {
  category = (redFlags.length > 0 || budgetScore === 0) ? 'warm' : 'hot'; // red flags or no budget = a human checks first
} else if (totalScore >= warm) {
  category = 'warm';
} else {
  category = 'cold';
}

return {
  json: {
    // lead
    source: lead.source,
    name: lead.name,
    email: lead.email,
    company: lead.company || ai.company || '', // form value first, then AI from message text
    website: lead.website,
    budget: lead.budget,
    timeline: lead.timeline,
    subject: lead.subject,
    message: lead.message,
    received_at: lead.received_at,
    source_id: lead.source_id,
    processed_at: lead.processed_at,
    thread_id: lead.thread_id || '', // lets Gmail Draft reply in the same thread
    // scoring
    category,
    total_score: totalScore,
    budget_score: budgetScore,
    authority_score: authorityScore,
    need_score: needScore,
    timeline_score: timelineScore,
    budget_evidence: ai.budget_evidence || '',
    authority_evidence: ai.authority_evidence || '',
    need_evidence: ai.need_evidence || '',
    timeline_evidence: ai.timeline_evidence || '',
    red_flags: redFlags.join(', '),
    // AI text
    summary: ai.summary || '',
    next_action: ai.next_action || '',
    language: ai.language || '',
    reply_draft: ai.reply_draft || '',
  },
};
